mkitem!{mkstruct!{# [doc = " A thread local storage (TLS) key which owns its contents."] # [doc = ""] # [doc = " This key uses the fastest implementation available on the target platform."] # [doc = " It is instantiated with the [`thread_local!`] macro and the"] # [doc = " primary method is the [`with`] method, though there are helpers to make"] # [doc = " working with [`Cell`] types easier."] # [doc = ""] # [doc = " The [`with`] method yields a reference to the contained value which cannot"] # [doc = " outlive the current thread or escape the given closure."] # [doc = ""] # [doc = " [`thread_local!`]: crate::thread_local"] # [doc = ""] # [doc = " # Initialization and Destruction"] # [doc = ""] # [doc = " Initialization is dynamically performed on the first call to a setter (e.g."] # [doc = " [`with`]) within a thread, and values that implement [`Drop`] get"] # [doc = " destructed when a thread exits. Some platform-specific caveats apply, which"] # [doc = " are explained below."] # [doc = " Note that if the destructor panics, the whole process will be [aborted]."] # [doc = ""] # [doc = " A `LocalKey`'s initializer cannot recursively depend on itself. Using a"] # [doc = " `LocalKey` in this way may cause panics, aborts, or infinite recursion on"] # [doc = " the first call to `with`."] # [doc = ""] # [doc = " [aborted]: crate::process::abort"] # [doc = ""] # [doc = " # Single-thread Synchronization"] # [doc = ""] # [doc = " Though there is no potential race with other threads, it is still possible to"] # [doc = " obtain multiple references to the thread-local data in different places on"] # [doc = " the call stack. For this reason, only shared (`&T`) references may be obtained."] # [doc = ""] # [doc = " To allow obtaining an exclusive mutable reference (`&mut T`), typically a"] # [doc = " [`Cell`] or [`RefCell`] is used (see the [`std::cell`] for more information"] # [doc = " on how exactly this works). To make this easier there are specialized"] # [doc = " implementations for [`LocalKey<Cell<T>>`] and [`LocalKey<RefCell<T>>`]."] # [doc = ""] # [doc = " [`std::cell`]: `crate::cell`"] # [doc = " [`LocalKey<Cell<T>>`]: struct.LocalKey.html#impl-LocalKey<Cell<T>>"] # [doc = " [`LocalKey<RefCell<T>>`]: struct.LocalKey.html#impl-LocalKey<RefCell<T>>"] # [doc = ""] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::Cell;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " // explicit `const {}` block enables more efficient initialization"] # [doc = " thread_local!(static FOO: Cell<u32> = const { Cell::new(1) });"] # [doc = ""] # [doc = " assert_eq!(FOO.get(), 1);"] # [doc = " FOO.set(2);"] # [doc = ""] # [doc = " // each thread starts out with the initial value of 1"] # [doc = " let t = thread::spawn(move || {"] # [doc = "     assert_eq!(FOO.get(), 1);"] # [doc = "     FOO.set(3);"] # [doc = " });"] # [doc = ""] # [doc = " // wait for the thread to complete and bail out on panic"] # [doc = " t.join().unwrap();"] # [doc = ""] # [doc = " // we retain our original value of 2 despite the child thread"] # [doc = " assert_eq!(FOO.get(), 2);"] # [doc = " ```"] # [doc = ""] # [doc = " # Platform-specific behavior"] # [doc = ""] # [doc = " Note that a \"best effort\" is made to ensure that destructors for types"] # [doc = " stored in thread local storage are run, but not all platforms can guarantee"] # [doc = " that destructors will be run for all types in thread local storage. For"] # [doc = " example, there are a number of known caveats where destructors are not run:"] # [doc = ""] # [doc = " 1. On Unix systems when pthread-based TLS is being used, destructors will"] # [doc = "    not be run for TLS values on the main thread when it exits. Note that the"] # [doc = "    application will exit immediately after the main thread exits as well."] # [doc = " 2. On all platforms it's possible for TLS to re-initialize other TLS slots"] # [doc = "    during destruction. Some platforms ensure that this cannot happen"] # [doc = "    infinitely by preventing re-initialization of any slot that has been"] # [doc = "    destroyed, but not all platforms have this guard. Those platforms that do"] # [doc = "    not guard typically have a synthetic limit after which point no more"] # [doc = "    destructors are run."] # [doc = " 3. When the process exits on Windows systems, TLS destructors may only be"] # [doc = "    run on the thread that causes the process to exit. This is because the"] # [doc = "    other threads may be forcibly terminated."] # [doc = ""] # [doc = " ## Synchronization in thread-local destructors"] # [doc = ""] # [doc = " On Windows, synchronization operations (such as [`JoinHandle::join`]) in"] # [doc = " thread local destructors are prone to deadlocks and so should be avoided."] # [doc = " This is because the [loader lock] is held while a destructor is run. The"] # [doc = " lock is acquired whenever a thread starts or exits or when a DLL is loaded"] # [doc = " or unloaded. Therefore these events are blocked for as long as a thread"] # [doc = " local destructor is running."] # [doc = ""] # [doc = " [loader lock]: https://docs.microsoft.com/en-us/windows/win32/dlls/dynamic-link-library-best-practices"] # [doc = " [`JoinHandle::join`]: crate::thread::JoinHandle::join"] # [doc = " [`with`]: LocalKey::with"] # [cfg_attr (not (test) , rustc_diagnostic_item = "LocalKey")] # [stable (feature = "rust1" , since = "1.0.0")] pub struct LocalKey < T : 'static > { inner : fn (Option < & mut Option < T > >) -> * const T , }}}
