mkitem!{# [doc = " Declare a new thread local storage key of type [`std::thread::LocalKey`]."] # [doc = ""] # [doc = " # Syntax"] # [doc = ""] # [doc = " The macro wraps any number of static declarations and makes them thread local."] # [doc = " Publicity and attributes for each static are allowed. Example:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::{Cell, RefCell};"] # [doc = ""] # [doc = " thread_local! {"] # [doc = "     pub static FOO: Cell<u32> = const { Cell::new(1) };"] # [doc = ""] # [doc = "     static BAR: RefCell<Vec<f32>> = RefCell::new(vec![1.0, 2.0]);"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(FOO.get(), 1);"] # [doc = " BAR.with_borrow(|v| assert_eq!(v[1], 2.0));"] # [doc = " ```"] # [doc = ""] # [doc = " Note that only shared references (`&T`) to the inner data may be obtained, so a"] # [doc = " type such as [`Cell`] or [`RefCell`] is typically used to allow mutating access."] # [doc = ""] # [doc = " This macro supports a special `const {}` syntax that can be used"] # [doc = " when the initialization expression can be evaluated as a constant."] # [doc = " This can enable a more efficient thread local implementation that"] # [doc = " can avoid lazy initialization. For types that do not"] # [doc = " [need to be dropped][crate::mem::needs_drop], this can enable an"] # [doc = " even more efficient implementation that does not need to"] # [doc = " track any additional state."] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::RefCell;"] # [doc = ""] # [doc = " thread_local! {"] # [doc = "     pub static FOO: RefCell<Vec<u32>> = const { RefCell::new(Vec::new()) };"] # [doc = " }"] # [doc = ""] # [doc = " FOO.with_borrow(|v| assert_eq!(v.len(), 0));"] # [doc = " ```"] # [doc = ""] # [doc = " See [`LocalKey` documentation][`std::thread::LocalKey`] for more"] # [doc = " information."] # [doc = ""] # [doc = " [`std::thread::LocalKey`]: crate::thread::LocalKey"] # [macro_export] # [stable (feature = "rust1" , since = "1.0.0")] # [cfg_attr (not (test) , rustc_diagnostic_item = "thread_local_macro")] # [allow_internal_unstable (thread_local_internals)] macro_rules ! thread_local { () => { } ; ($ (# [$ attr : meta]) * $ vis : vis static $ name : ident : $ t : ty = const $ init : block ; $ ($ rest : tt) *) => ($ crate :: thread :: local_impl :: thread_local_inner ! ($ (# [$ attr]) * $ vis $ name , $ t , const $ init) ; $ crate :: thread_local ! ($ ($ rest) *) ;) ; ($ (# [$ attr : meta]) * $ vis : vis static $ name : ident : $ t : ty = const $ init : block) => ($ crate :: thread :: local_impl :: thread_local_inner ! ($ (# [$ attr]) * $ vis $ name , $ t , const $ init) ;) ; ($ (# [$ attr : meta]) * $ vis : vis static $ name : ident : $ t : ty = $ init : expr ; $ ($ rest : tt) *) => ($ crate :: thread :: local_impl :: thread_local_inner ! ($ (# [$ attr]) * $ vis $ name , $ t , $ init) ; $ crate :: thread_local ! ($ ($ rest) *) ;) ; ($ (# [$ attr : meta]) * $ vis : vis static $ name : ident : $ t : ty = $ init : expr) => ($ crate :: thread :: local_impl :: thread_local_inner ! ($ (# [$ attr]) * $ vis $ name , $ t , $ init) ;) ; }}
