macro_rules! panic_access_error_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function panic_access_error in module {}", module_path!());
    };
}

mkfn!{
    panic_access_error_introspect!();
    # [cfg_attr (not (feature = "panic_immediate_abort") , inline (never))] # [track_caller] # [cold] fn panic_access_error (err : AccessError) -> ! { panic ! ("cannot access a Thread Local Storage value during or after destruction: {err:?}") }
}
mkitem!{mkimpl!{impl < T : 'static > LocalKey < T > { # [doc (hidden)] # [unstable (feature = "thread_local_internals" , reason = "recently added to create a key" , issue = "none")] pub const unsafe fn new (inner : fn (Option < & mut Option < T > >) -> * const T) -> LocalKey < T > { LocalKey { inner } } # [doc = " Acquires a reference to the value in this TLS key."] # [doc = ""] # [doc = " This will lazily initialize the value if this thread has not referenced"] # [doc = " this key yet."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This function will `panic!()` if the key currently has its"] # [doc = " destructor running, and it **may** panic if the destructor has"] # [doc = " previously been run for this thread."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " thread_local! {"] # [doc = "     pub static STATIC: String = String::from(\"I am\");"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!("] # [doc = "     STATIC.with(|original_value| format!(\"{original_value} initialized\")),"] # [doc = "     \"I am initialized\","] # [doc = " );"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn with < F , R > (& 'static self , f : F) -> R where F : FnOnce (& T) -> R , { match self . try_with (f) { Ok (r) => r , Err (err) => panic_access_error (err) , } } # [doc = " Acquires a reference to the value in this TLS key."] # [doc = ""] # [doc = " This will lazily initialize the value if this thread has not referenced"] # [doc = " this key yet. If the key has been destroyed (which may happen if this is called"] # [doc = " in a destructor), this function will return an [`AccessError`]."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This function will still `panic!()` if the key is uninitialized and the"] # [doc = " key's initializer panics."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " thread_local! {"] # [doc = "     pub static STATIC: String = String::from(\"I am\");"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!("] # [doc = "     STATIC.try_with(|original_value| format!(\"{original_value} initialized\")),"] # [doc = "     Ok(String::from(\"I am initialized\")),"] # [doc = " );"] # [doc = " ```"] # [stable (feature = "thread_local_try_with" , since = "1.26.0")] # [inline] pub fn try_with < F , R > (& 'static self , f : F) -> Result < R , AccessError > where F : FnOnce (& T) -> R , { let thread_local = unsafe { (self . inner) (None) . as_ref () . ok_or (AccessError) ? } ; Ok (f (thread_local)) } # [doc = " Acquires a reference to the value in this TLS key, initializing it with"] # [doc = " `init` if it wasn't already initialized on this thread."] # [doc = ""] # [doc = " If `init` was used to initialize the thread local variable, `None` is"] # [doc = " passed as the first argument to `f`. If it was already initialized,"] # [doc = " `Some(init)` is passed to `f`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This function will panic if the key currently has its destructor"] # [doc = " running, and it **may** panic if the destructor has previously been run"] # [doc = " for this thread."] fn initialize_with < F , R > (& 'static self , init : T , f : F) -> R where F : FnOnce (Option < T > , & T) -> R , { let mut init = Some (init) ; let reference = unsafe { match (self . inner) (Some (& mut init)) . as_ref () { Some (r) => r , None => panic_access_error (AccessError) , } } ; f (init , reference) } }}}
